window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-77e485cbe4c2b9bb"]={"versions": [{"id": "FIG-77e485cbe4c2b9bb", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML 2.x Sequenzdiagramm (Interaktions- und Ablauf-Szenario).</li>\n<li><strong>Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R23-11, Spezifikation <code>AUTOSAR_AP_EXP_SWArchitecture</code>, Kapitel 11.3.1 (<em>Persistency</em>).</li>\n<li><strong>Technischer Zweck:</strong> Detaillierung des Standard-Persistierungsablaufs für schlüsselwertbasierte Daten (<em>Store Persistent Data with Unique ID</em> via <code>KeyValueStorage</code>). Es visualisiert das zweistufige Commit-Modell (RAM-Pufferung vs. synchronisierter NVRAM-/Disk-Flush) sowie die optionale, manifestgesteuerte Krypto-Integration vor der Übergabe an das Betriebssystem.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Lebenslinien & Stereotypen:</strong></li>\n<li><code>:Adaptive Application</code> (Akteur / Prozess-Instanz): Nutzt die standardisierte funktionale C++-API von <code>ara::per</code>.</li>\n<li><code>«aapFunctionalCluster» :Persistency</code> (Plattform-Basisdienst): Realisiert den Functional Cluster <code>ara::per</code>; verwaltet In-Memory-Caches, Serialisierung, Redundanzprüfungen und Persistierungslogik.</li>\n<li><code>:Operating System</code> (Akteur / POSIX-Subsystem): Abstrahiert Dateisystem-, VFS- und Blocktreiberzugriffe über standardisierte POSIX-Systemschnittstellen.</li>\n<li><code>«aapFunctionalCluster» :Cryptography</code> (Plattform-Basisdienst): Realisiert den Functional Cluster <code>ara::crypto</code>; stellt kryptographische Transformationen, Algorithmen und Schlüsselkontexte bereit.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>OpenKeyValueStorage(): KeyValueStorage</code>: Fabrikmethode/Getter am Persistency-Cluster zur Erlangung eines typisierten Storage-Handles (<code>ara::per::KeyValueStorage</code>).</li>\n<li><code>SetValue()</code>: Typisierte Schreiboperation auf den lokalen In-Memory-Puffer des Key-Value-Speichers.</li>\n<li><code>SyncToStorage()</code>: Synchronisationsbefehl zum physischen Flush der gepufferten Änderungen in den permanenten Speicher.</li>\n<li><code>open()</code>, <code>write()</code>: Low-Level-POSIX-Systemaufrufe zur Interaktion mit dem Dateisystem/Persistent Storage.</li>\n<li><code>ProcessBlock()</code>: Symmetrische Blockverschlüsselungs- bzw. Transformationsoperation der Krypto-Pipeline.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Konfigurations- und Manifestelemente:</strong></li>\n<li><code>KeySlotMapping</code>: ARXML-Manifest-Zuordnung zwischen einem logischen Persistency-Port/Storage und einem konkreten physischen/logischen Crypto-KeySlot (<code>ara::crypto::keys</code>).</li>\n<li><code>keySlotUsage = encryption</code>: Manifest-Attribut, welches die kryptographische Verschleierung vor dem Dateisystem-Schreibvorgang erzwingt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung des Storage-Handles:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>:Adaptive Application</code> ruft synchron <code>OpenKeyValueStorage()</code> auf. <code>:Persistency</code> instanziiert bzw. bindet die <code>KeyValueStorage</code>-Ressource und gibt das Handle zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>In-Memory-Modifikation (Entkoppelter Schreibvorgang):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Applikation ruft <code>SetValue()</code> auf. <code>:Persistency</code> aktualisiert den Wert ausschließlich im flüchtigen Prozess-Arbeitsspeicher (Cache). Zu diesem Zeitpunkt findet keinerlei I/O-Interaktion mit dem Filesystem oder Krypto-Cluster statt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Flush-Trigger (<code>SyncToStorage</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Applikation stößt über <code>SyncToStorage()</code> die eigentliche Persistierungskette an.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Storage-Öffnung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>:Persistency</code> initiiert den I/O-Kanal über den Aufruf <code>open()</code> am <code>:Operating System</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Konditionale Verschlüsselung (<code>alt</code>-Fragment):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Guard-Bedingung:</em> <code>[KeySlotMapping exists in Manifest and keySlotUsage = encryption]</code>.</li>\n<li><em>Sub-Interaktion (<code>ref</code>):</em> Ausführung des referenzierten Krypto-Setups <code>Initialize Cipher</code> (Allokation des Krypto-Kontextes, Import/Bindung des Schlüssels aus dem definierten KeySlot via <code>ara::crypto</code>).</li>\n<li><em>Transformation:</em> <code>:Persistency</code> übergibt die serialisierten Nutzdatenblöcke via <code>ProcessBlock()</code> synchron an <code>:Cryptography</code> und erhält den Chiffretext zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Persistenter I/O-Schreibzugriff:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>:Persistency</code> schreibt den Datenstrom (Plaintext oder Chiffretext, ggf. erweitert um konfigurierte Redundanz-/CRC-Header) über den POSIX-Aufruf <code>write()</code> an das <code>:Operating System</code>. Nach Rückkehr des I/O-Aufrufs terminiert <code>SyncToStorage()</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Pufferungs- & Transaktionssemantik:</strong></li>\n<li><code>SetValue()</code> garantiert <strong>keine</strong> Ausfallsicherheit gegen Power-Loss oder Crash. Persistenz wird erst mit dem erfolgreichen Abschluss von <code>SyncToStorage()</code> sichergestellt.</li>\n<li><code>SyncToStorage()</code> ist ein blockierender, I/O- und rechenintensiver Aufruf. In harten Echtzeitkontexten darf <code>SyncToStorage()</code> nicht hochfrequent/zyklisch aufgerufen werden; Modifikationen sind per <code>SetValue()</code> zu aggregieren und gezielt transaktionsorientiert zu flashen.</li>\n<li><strong>Transparente Verschlüsselung via Manifest:</strong></li>\n<li>Die Anwendungssoftware interagiert rein mit Klartextdaten über <code>SetValue()</code>. Die Verschlüsselung ist vollkommen entkoppelt und wird ausschließlich über die Manifest-Modellierung gesteuert (<code>KeySlotMapping</code>).</li>\n<li><strong>Fehler- und Determinismusbehandlung:</strong></li>\n<li>Schlägt <code>open()</code>, <code>ProcessBlock()</code> oder <code>write()</code> fehl (z. B. Speicher voll, Krypto-Schlüssel im Slot ungültig/gesperrt, I/O-Fehler), propagiert <code>SyncToStorage()</code> einen entsprechenden <code>ara::core::Result&lt;void&gt;</code>-Fehlercode (<code>ara::per::PerErrc</code>). Die Applikation muss diesen Rückgabewert zwingend auswerten, um Datenverlust zu detektieren.</li>\n</ul>"}, {"id": "FIG-884a6a447fcf4783", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML 2.x Sequenzdiagramm (Interaktions- und Ablauf-Szenario).</li>\n<li><strong>Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R23-11, Spezifikation <code>AUTOSAR_AP_EXP_SWArchitecture</code>, Kapitel 11.3.1 (<em>Persistency</em>).</li>\n<li><strong>Technischer Zweck:</strong> Detaillierung des Standard-Persistierungsablaufs für schlüsselwertbasierte Daten (<em>Store Persistent Data with Unique ID</em> via <code>KeyValueStorage</code>). Es visualisiert das zweistufige Commit-Modell (RAM-Pufferung vs. synchronisierter NVRAM-/Disk-Flush) sowie die optionale, manifestgesteuerte Krypto-Integration vor der Übergabe an das Betriebssystem.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Lebenslinien & Stereotypen:</strong></li>\n<li><code>:Adaptive Application</code> (Akteur / Prozess-Instanz): Nutzt die standardisierte funktionale C++-API von <code>ara::per</code>.</li>\n<li><code>«aapFunctionalCluster» :Persistency</code> (Plattform-Basisdienst): Realisiert den Functional Cluster <code>ara::per</code>; verwaltet In-Memory-Caches, Serialisierung, Redundanzprüfungen und Persistierungslogik.</li>\n<li><code>:Operating System</code> (Akteur / POSIX-Subsystem): Abstrahiert Dateisystem-, VFS- und Blocktreiberzugriffe über standardisierte POSIX-Systemschnittstellen.</li>\n<li><code>«aapFunctionalCluster» :Cryptography</code> (Plattform-Basisdienst): Realisiert den Functional Cluster <code>ara::crypto</code>; stellt kryptographische Transformationen, Algorithmen und Schlüsselkontexte bereit.</li>\n<li><code>«aapInformative»</code>: Stereotyp zur Kennzeichnung nicht-normativer bzw. betriebssystemspezifischer Interaktionen (<code>open()</code>, <code>write()</code>).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>OpenKeyValueStorage(): KeyValueStorage</code>: Fabrikmethode/Getter am Persistency-Cluster zur Erlangung eines typisierten Storage-Handles (<code>ara::per::KeyValueStorage</code>).</li>\n<li><code>SetValue()</code>: Typisierte Schreiboperation auf den lokalen In-Memory-Puffer des Key-Value-Speichers.</li>\n<li><code>SyncToStorage()</code>: Synchronisationsbefehl zum physischen Flush der gepufferten Änderungen in den permanenten Speicher.</li>\n<li><code>open()</code>, <code>write()</code> (mit Stereotyp <code>«aapInformative»</code>): Low-Level-POSIX-Systemaufrufe zur Interaktion mit dem Dateisystem/Persistent Storage.</li>\n<li><code>ProcessBlock()</code>: Symmetrische Blockverschlüsselungs- bzw. Transformationsoperation der Krypto-Pipeline.</li>\n<li><code>Store Redundant Data</code> (referenzierte Interaktion / <code>ref</code>): Sub-Ablauf zur Speicherung redundanter Datenstrukturen zur Erkennung und Korrektur von Speicherfehlern.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Konfigurations- und Manifestelemente:</strong></li>\n<li><code>KeySlotMapping</code>: ARXML-Manifest-Zuordnung zwischen einem logischen Persistency-Port/Storage und einem konkreten physischen/logischen Crypto-KeySlot (<code>ara::crypto::keys</code>).</li>\n<li><code>keySlotUsage = encryption</code>: Manifest-Attribut, welches die kryptographische Verschleierung vor dem Dateisystem-Schreibvorgang erzwingt.</li>\n<li><code>Redundancy enabled in Manifest</code>: Manifest-Bedingung zur Aktivierung redundanter Datenspeicherung in <code>Persistency</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung des Storage-Handles:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>:Adaptive Application</code> ruft synchron <code>OpenKeyValueStorage()</code> auf. <code>:Persistency</code> instanziiert bzw. bindet die <code>KeyValueStorage</code>-Ressource und gibt das Handle zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>In-Memory-Modifikation (Entkoppelter Schreibvorgang):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Applikation ruft <code>SetValue()</code> auf. <code>:Persistency</code> aktualisiert den Wert ausschließlich im flüchtigen Prozess-Arbeitsspeicher (Cache). Zu diesem Zeitpunkt findet keinerlei I/O-Interaktion mit dem Filesystem oder Krypto-Cluster statt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Flush-Trigger (<code>SyncToStorage</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Applikation stößt über <code>SyncToStorage()</code> die eigentliche Persistierungskette an.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Storage-Öffnung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>:Persistency</code> initiiert den I/O-Kanal über den informativen POSIX-Aufruf <code>open()</code> («aapInformative») am <code>:Operating System</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Konditionale Verschlüsselung (<code>alt</code>-Fragment):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Guard-Bedingung:</em> <code>[KeySlotMapping exists in Manifest and keySlotUsage = encryption]</code>.</li>\n<li><em>Sub-Interaktion (<code>ref</code>):</em> Ausführung des referenzierten Krypto-Setups <code>Initialize Cipher</code> (Allokation des Krypto-Kontextes, Import/Bindung des Schlüssels aus dem definierten KeySlot via <code>ara::crypto</code>).</li>\n<li><em>Transformation:</em> <code>:Persistency</code> übergibt die serialisierten Nutzdatenblöcke via <code>ProcessBlock()</code> synchron an <code>:Cryptography</code> und erhält den Chiffretext zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Persistenter I/O-Schreibzugriff:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>:Persistency</code> schreibt den Datenstrom über den informativen POSIX-Aufruf <code>write()</code> («aapInformative») an das <code>:Operating System</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Konditionale Redundanzspeicherung (<code>alt</code>-Fragment):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Guard-Bedingung:</em> <code>[Redundancy enabled in Manifest]</code>.</li>\n<li><em>Sub-Interaktion (<code>ref</code>):</em> <code>:Persistency</code> führt die referenzierte Interaktion <code>Store Redundant Data</code> aus, um redundante Daten zur Fehlererkennung und -korrektur im persistenten Speicher abzulegen. Nach Abschluss terminiert <code>SyncToStorage()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Pufferungs- & Transaktionssemantik:</strong></li>\n<li><code>SetValue()</code> garantiert <strong>keine</strong> Ausfallsicherheit gegen Power-Loss oder Crash. Persistenz wird erst mit dem erfolgreichen Abschluss von <code>SyncToStorage()</code> sichergestellt.</li>\n<li><code>SyncToStorage()</code> ist ein blockierender, I/O- und rechenintensiver Aufruf. In harten Echtzeitkontexten darf <code>SyncToStorage()</code> nicht hochfrequent/zyklisch aufgerufen werden; Modifikationen sind per <code>SetValue()</code> zu aggregieren und gezielt transaktionsorientiert zu flashen.</li>\n<li><strong>Transparente Verschlüsselung via Manifest:</strong></li>\n<li>Die Anwendungssoftware interagiert rein mit Klartextdaten über <code>SetValue()</code>. Die Verschlüsselung ist vollkommen entkoppelt und wird ausschließlich über die Manifest-Modellierung gesteuert (<code>KeySlotMapping</code>).</li>\n<li><strong>Fehler- und Determinismusbehandlung:</strong></li>\n<li>Schlägt <code>open()</code>, <code>ProcessBlock()</code> oder <code>write()</code> fehl (z. B. Speicher voll, Krypto-Schlüssel im Slot ungültig/gesperrt, I/O-Fehler), propagiert <code>SyncToStorage()</code> einen entsprechenden <code>ara::core::Result&lt;void&gt;</code>-Fehlercode (<code>ara::per::PerErrc</code>). Die Applikation muss diesen Rückgabewert zwingend auswerten, um Datenverlust zu detektieren.</li>\n</ul>"}, {"id": "FIG-cd074fec3273c0cb", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML 2.x Sequenzdiagramm (Interaktions- und Ablauf-Szenario).</li>\n<li><strong>Kontext:</strong> AUTOSAR Adaptive Platform (AP), Release R23-11, Spezifikation <code>AUTOSAR_AP_EXP_SWArchitecture</code>, Kapitel 11.3.1 (<em>Persistency</em>).</li>\n<li><strong>Technischer Zweck:</strong> Detaillierung des Standard-Persistierungsablaufs für schlüsselwertbasierte Daten (<em>Store Persistent Data with Unique ID</em> via <code>KeyValueStorage</code>). Es visualisiert das zweistufige Commit-Modell (RAM-Pufferung vs. synchronisierter NVRAM-/Disk-Flush) sowie die optionale, manifestgesteuerte Krypto-Integration vor der Übergabe an das Betriebssystem.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Lebenslinien & Stereotypen:</strong></li>\n<li><code>:Adaptive Application</code> (Akteur / Prozess-Instanz): Nutzt die standardisierte funktionale C++-API von <code>ara::per</code>.</li>\n<li><code>«aapFunctionalCluster» :Persistency</code> (Plattform-Basisdienst): Realisiert den Functional Cluster <code>ara::per</code>; verwaltet In-Memory-Caches, Serialisierung, Redundanzprüfungen und Persistierungslogik.</li>\n<li><code>:Operating System</code> (Akteur / POSIX-Subsystem): Abstrahiert Dateisystem-, VFS- und Blocktreiberzugriffe über standardisierte POSIX-Systemschnittstellen.</li>\n<li><code>«aapFunctionalCluster» :Cryptography</code> (Plattform-Basisdienst): Realisiert den Functional Cluster <code>ara::crypto</code>; stellt kryptographische Transformationen, Algorithmen und Schlüsselkontexte bereit.</li>\n<li><code>«aapInformative»</code>: Stereotyp zur Kennzeichnung nicht-normativer bzw. betriebssystemspezifischer Interaktionen (<code>open()</code>, <code>write()</code>).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen & Operationen:</strong></li>\n<li><code>OpenKeyValueStorage(): KeyValueStorage</code>: Fabrikmethode/Getter am Persistency-Cluster zur Erlangung eines typisierten Storage-Handles (<code>ara::per::KeyValueStorage</code>).</li>\n<li><code>SetValue()</code>: Typisierte Schreiboperation auf den lokalen In-Memory-Puffer des Key-Value-Speichers.</li>\n<li><code>SyncToStorage()</code>: Synchronisationsbefehl zum physischen Flush der gepufferten Änderungen in den permanenten Speicher.</li>\n<li><code>open()</code>, <code>write()</code> (mit Stereotyp <code>«aapInformative»</code>): Low-Level-POSIX-Systemaufrufe zur Interaktion mit dem Dateisystem/Persistent Storage.</li>\n<li><code>ProcessBlock()</code>: Symmetrische Blockverschlüsselungs- bzw. Transformationsoperation der Krypto-Pipeline.</li>\n<li><code>Store Redundant Data</code> (referenzierte Interaktion / <code>ref</code>): Sub-Ablauf zur Speicherung redundanter Datenstrukturen zur Erkennung und Korrektur von Speicherfehlern.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Konfigurations- und Manifestelemente:</strong></li>\n<li><code>KeySlotMapping</code>: ARXML-Manifest-Zuordnung zwischen einem logischen Persistency-Port/Storage und einem konkreten physischen/logischen Crypto-KeySlot (<code>ara::crypto::keys</code>).</li>\n<li><code>keySlotUsage = encryption</code>: Manifest-Attribut, welches die kryptographische Verschleierung vor dem Dateisystem-Schreibvorgang erzwingt.</li>\n<li><code>Redundancy enabled in Manifest</code>: Manifest-Bedingung zur Aktivierung redundanter Datenspeicherung in <code>Persistency</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung des Storage-Handles:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>:Adaptive Application</code> ruft synchron <code>OpenKeyValueStorage()</code> auf. <code>:Persistency</code> instanziiert bzw. bindet die <code>KeyValueStorage</code>-Ressource und gibt das Handle zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>In-Memory-Modifikation (Entkoppelter Schreibvorgang):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Applikation ruft <code>SetValue()</code> auf. <code>:Persistency</code> aktualisiert den Wert ausschließlich im flüchtigen Prozess-Arbeitsspeicher (Cache). Zu diesem Zeitpunkt findet keinerlei I/O-Interaktion mit dem Filesystem oder Krypto-Cluster statt.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Flush-Trigger (<code>SyncToStorage</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Die Applikation stößt über <code>SyncToStorage()</code> die eigentliche Persistierungskette an.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Storage-Öffnung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>:Persistency</code> initiiert den I/O-Kanal über den informativen POSIX-Aufruf <code>open()</code> («aapInformative») am <code>:Operating System</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Konditionale Verschlüsselung (<code>alt</code>-Fragment):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Guard-Bedingung:</em> <code>[KeySlotMapping exists in Manifest and keySlotUsage = encryption]</code>.</li>\n<li><em>Sub-Interaktion (<code>ref</code>):</em> Ausführung des referenzierten Krypto-Setups <code>Initialize Cipher</code> (Allokation des Krypto-Kontextes, Import/Bindung des Schlüssels aus dem definierten KeySlot via <code>ara::crypto</code>).</li>\n<li><em>Transformation:</em> <code>:Persistency</code> übergibt die serialisierten Nutzdatenblöcke via <code>ProcessBlock()</code> synchron an <code>:Cryptography</code> und erhält den Chiffretext zurück.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Persistenter I/O-Schreibzugriff:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>:Persistency</code> schreibt den Datenstrom über den informativen POSIX-Aufruf <code>write()</code> («aapInformative») an das <code>:Operating System</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Konditionale Redundanzspeicherung (<code>alt</code>-Fragment):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Guard-Bedingung:</em> <code>[Redundancy enabled in Manifest]</code>.</li>\n<li><em>Sub-Interaktion (<code>ref</code>):</em> <code>:Persistency</code> führt die referenzierte Interaktion <code>Store Redundant Data</code> aus, um redundante Daten zur Fehlererkennung und -korrektur im persistenten Speicher abzulegen. Nach Abschluss terminiert <code>SyncToStorage()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Pufferungs- & Transaktionssemantik:</strong></li>\n<li><code>SetValue()</code> garantiert <strong>keine</strong> Ausfallsicherheit gegen Power-Loss oder Crash. Persistenz wird erst mit dem erfolgreichen Abschluss von <code>SyncToStorage()</code> sichergestellt.</li>\n<li><code>SyncToStorage()</code> ist ein blockierender, I/O- und rechenintensiver Aufruf. In harten Echtzeitkontexten darf <code>SyncToStorage()</code> nicht hochfrequent/zyklisch aufgerufen werden; Modifikationen sind per <code>SetValue()</code> zu aggregieren und gezielt transaktionsorientiert zu flashen.</li>\n<li><strong>Transparente Verschlüsselung via Manifest:</strong></li>\n<li>Die Anwendungssoftware interagiert rein mit Klartextdaten über <code>SetValue()</code>. Die Verschlüsselung ist vollkommen entkoppelt und wird ausschließlich über die Manifest-Modellierung gesteuert (<code>KeySlotMapping</code>).</li>\n<li><strong>Fehler- und Determinismusbehandlung:</strong></li>\n<li>Schlägt <code>open()</code>, <code>ProcessBlock()</code> oder <code>write()</code> fehl (z. B. Speicher voll, Krypto-Schlüssel im Slot ungültig/gesperrt, I/O-Fehler), propagiert <code>SyncToStorage()</code> einen entsprechenden <code>ara::core::Result&lt;void&gt;</code>-Fehlercode (<code>ara::per::PerErrc</code>). Die Applikation muss diesen Rückgabewert zwingend auswerten, um Datenverlust zu detektieren.</li>\n</ul>"}], "trans": [{"from": "FIG-77e485cbe4c2b9bb", "to": "FIG-884a6a447fcf4783", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Kombiniertes Fragment (<code>alt</code>):</strong> Ergänzung des bedingten Fragments <code>[Redundancy enabled in Manifest]</code> mit der referenzierten Interaktion <code>ref Store Redundant Data</code> am Ende des Persistierungsablaufs.</li>\n<li><strong>Stereotyp <code>«aapInformative»</code>:</strong> Ergänzung des Stereotyps <code>«aapInformative»</code> an den POSIX-Systemaufrufen <code>open()</code> und <code>write()</code> zwischen <code>:Persistency</code> und <code>:Operating System</code>.</li>\n</ul>"}, {"from": "FIG-884a6a447fcf4783", "to": "FIG-cd074fec3273c0cb", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
